p.deleted_at IS NULL
    AND (p.owner_user_id=#{actor} OR EXISTS (SELECT 1 FROM sop_project_member m WHERE m.project_id=p.id AND m.user_id=#{actor} AND m.member_status=1))
    AND p.owner_user_id=#{actor}
    AND (LOCATE(#{keyword},p.name)>0 OR LOCATE(#{keyword},p.code)>0)
    AND p.status=#{status}

m.project_id=#{projectId}
    AND m.member_status=#{status}
    AND (LOCATE(#{keyword},u.username)>0 OR LOCATE(#{keyword},u.real_name)>0)
